import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"标签页与多窗口","description":"","frontmatter":{},"headers":[],"relativePath":"zh/usage.md","filePath":"zh/usage.md","lastUpdated":null}'),d={name:"zh/usage.md"};function l(n,t,s,h,i,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="标签页与多窗口" tabindex="-1">标签页与多窗口 <a class="header-anchor" href="#标签页与多窗口" aria-label="Permalink to &quot;标签页与多窗口&quot;">​</a></h1><p>应用是无边框桌面外壳，窗口上部是自绘标题栏（内置浏览器式标签条），下部是 web 内容区。</p><h2 id="标题栏-左侧-→-右侧" tabindex="-1">标题栏（左侧 → 右侧） <a class="header-anchor" href="#标题栏-左侧-→-右侧" aria-label="Permalink to &quot;标题栏（左侧 → 右侧）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>应用图标 + 标题</td><td>显示应用名</td></tr><tr><td>固定站图标</td><td>仅<strong>核心窗口</strong>显示：DeepSeek UI / 网页版对话 / 用量充值</td></tr><tr><td>跳转核心窗口</td><td>仅<strong>副窗口</strong>显示，用于回到承载 DeepSeek UI 的那个窗口</td></tr><tr><td>标签条</td><td>动态标签 + 「＋」新建；空白处可拖动窗口、滚轮横向滚动</td></tr><tr><td>刷新</td><td>仅当前激活的是三个固定站之一时显示，用于重载该页</td></tr><tr><td>设置</td><td>打开设置页（<strong>终端</strong>也是设置页里的一项：设置 → 终端）</td></tr><tr><td>最小化 / 最大化 / 关闭</td><td>窗口控制</td></tr></tbody></table><blockquote><p>进入设置是<strong>覆盖层</strong>：底下的网页不会卸载，切回来仍是原状态。</p></blockquote><h2 id="标签页" tabindex="-1">标签页 <a class="header-anchor" href="#标签页" aria-label="Permalink to &quot;标签页&quot;">​</a></h2><h3 id="固定标签-仅核心窗口" tabindex="-1">固定标签（仅核心窗口） <a class="header-anchor" href="#固定标签-仅核心窗口" aria-label="Permalink to &quot;固定标签（仅核心窗口）&quot;">​</a></h3><p>三个固定站始终存在、<strong>不可关闭</strong>：</p><ol><li><strong>DeepSeek UI</strong> —— 内嵌的 DeepSeek Harness 主界面。</li><li><strong>网页版对话</strong> —— 内嵌 <a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">chat.deepseek.com</a>。</li><li><strong>用量 / 充值</strong> —— 内嵌 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>。</li></ol><h3 id="动态标签" tabindex="-1">动态标签 <a class="header-anchor" href="#动态标签" aria-label="Permalink to &quot;动态标签&quot;">​</a></h3><ul><li>来源：页面内链接的 <code>target=_blank</code> / <code>window.open</code>，或点标签条上的「＋」。</li><li>数量不设上限。</li><li><strong>保活策略</strong>：同时保活的网页为「固定站 + 你加星的标签 + 最近 3 个未加星的动态标签」。超出范围的标签<strong>仍然保留在标签条上</strong>，只是其网页被回收，切回时会重新加载。</li><li>标签只有<strong>被打开过</strong>之后才会真正加载网页。</li></ul><h3 id="「-」新建标签" tabindex="-1">「＋」新建标签 <a class="header-anchor" href="#「-」新建标签" aria-label="Permalink to &quot;「＋」新建标签&quot;">​</a></h3><p>按<a href="/zh/settings">设置</a>里的「新标签页」决定打开什么：</p><ul><li><strong>内置导航页</strong>（默认）——带搜索框、可切换搜索引擎、并显示你配置的常用站点；</li><li><strong>自定义网址</strong>——直接打开你填写的固定 URL。</li></ul><h3 id="标签操作" tabindex="-1">标签操作 <a class="header-anchor" href="#标签操作" aria-label="Permalink to &quot;标签操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td>单击</td><td>切换到该标签</td></tr><tr><td><code>Ctrl</code> / <code>Cmd</code> + 单击</td><td>用<strong>系统默认浏览器</strong>打开该标签的网址</td></tr><tr><td>中键单击</td><td>关闭标签</td></tr><tr><td>星标（☆）</td><td>保活固定：该标签的网页常驻，且<strong>不占用</strong>最近 3 个保活名额</td></tr><tr><td>拖动标签</td><td>在标签条内<strong>重新排序</strong>；拖到<strong>另一个窗口</strong>顶部的浅蓝遮罩上，可把标签<strong>移入该窗口</strong></td></tr><tr><td>右键</td><td>复制标签 / 关闭 / 在新窗口打开 / 移动到其它窗口</td></tr></tbody></table><h2 id="地址栏" tabindex="-1">地址栏 <a class="header-anchor" href="#地址栏" aria-label="Permalink to &quot;地址栏&quot;">​</a></h2><p>地址栏<strong>仅在动态标签激活时显示</strong>（固定站不显示）。</p><table tabindex="0"><thead><tr><th>输入</th><th>行为</th></tr></thead><tbody><tr><td><code>http(s):</code> / <code>about:</code></td><td>在应用内加载</td></tr><tr><td>其它协议（<code>mailto:</code>、<code>tel:</code>、自定义协议等）</td><td>交给系统默认程序打开</td></tr><tr><td>不是网址的内容</td><td>用设置的<strong>默认搜索引擎</strong>搜索</td></tr></tbody></table><p>地址栏左侧还有 <strong>后退 / 前进 / 刷新</strong>（加载中变为停止）。</p><h2 id="多窗口" tabindex="-1">多窗口 <a class="header-anchor" href="#多窗口" aria-label="Permalink to &quot;多窗口&quot;">​</a></h2><ul><li>在标签上右键「<strong>在新窗口打开</strong>」，即可开出一个<strong>完整副窗口</strong>（自带标签条）。</li><li>副窗口<strong>没有</strong>内核 UI 等三个固定站，标题栏位置显示「<strong>跳转核心窗口</strong>」按钮。</li><li>副窗口的窗口标题会显示「当前标签页标题 - 软件名」。</li><li><strong>核心窗口被关闭后</strong>，最早打开的副窗口会<strong>自动接管</strong>成为新的核心窗口，并获得三个固定站。</li></ul><h2 id="右键菜单" tabindex="-1">右键菜单 <a class="header-anchor" href="#右键菜单" aria-label="Permalink to &quot;右键菜单&quot;">​</a></h2><p>在任意输入框、或拖选出来的文本上<strong>右键</strong>，会给出<strong>剪切 / 复制 / 粘贴 / 全选</strong>：</p><ul><li>输入框里三项齐全；只选中了文本（不可编辑）时给出「复制 / 全选」；</li><li>既没选中内容、也不在输入框里时<strong>不弹菜单</strong>（标签条上的右键菜单是另一套，见上面的「标签操作」）；</li><li>内嵌网页（DeepSeek UI / 网页对话 / 动态标签）里的输入框同样支持。</li></ul><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><p>默认快捷键如下，三者都可在<a href="/zh/settings">设置 → 快捷键</a>里修改（「清空」即禁用）：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code> / <code>Cmd</code> + <code>Alt</code> + <code>H</code></td><td><strong>系统全局</strong>：在任何程序里按下都回到本应用主窗口（最小化或隐藏到托盘也能拉回来）</td></tr><tr><td><code>Ctrl</code> / <code>Cmd</code> + <code>T</code></td><td>在 DeepSeek UI 与终端（设置 → 终端）之间切换</td></tr><tr><td><code>F12</code></td><td>打开 / 关闭 DevTools 控制台（<strong>仅当「开发模式」开启时生效</strong>）</td></tr></tbody></table><h2 id="托盘" tabindex="-1">托盘 <a class="header-anchor" href="#托盘" aria-label="Permalink to &quot;托盘&quot;">​</a></h2><p>关闭到托盘后，可通过系统托盘图标：</p><ul><li>单击：显示 / 隐藏窗口；</li><li>右键菜单：「显示/隐藏窗口」「退出（同时结束 dsh）」。</li></ul><blockquote><p>关闭窗口并不结束 dsh；真正退出时应用会同步结束它管理的 dsh 进程，避免残留。 若没有可用托盘，关闭最后一个窗口会直接退出应用。</p></blockquote>',32)])])}const u=e(d,[["render",l]]);export{b as __pageData,u as default};
